def dico(q,k):
    x=np.exp(-q*T); E=np.exp(-k*eps); D={}
    base={'1':np.ones_like(eps),'e':eps,'e2':eps**2,'e3':eps**3,'T':T,'T2':T**2,'Te':T*eps,'Te2':T*eps**2,'1/T':1/T}
    for n,v in base.items(): D[n]=v
    for n,v in base.items():
        if n!='1': D['x*'+n]=x*v; D['E*'+n]=E*v; D['xE*'+n]=x*E*v
    D['x']=x; D['E']=E; D['xE']=x*E
    D['sqrt e']=np.sqrt(eps); D['log e']=np.log(eps)
    return D
def score(q,k,nterms=6):
